#!/usr/bin/env bash

set -e

#
# Write the commit id of the specs repository to the build file.
#
echo "json schema version"
VERSION=$(cat ../tracking-schemas/version.txt)

# Update version code
VERSION_OBJECT="../hermes/src/main/kotlin/com/dashlane/hermes/TrackingSchemasVersion.kt"

echo -n "package com.dashlane.hermes

import javax.annotation.processing.Generated

// Do not edit, code automatically generated by \"specs-version.sh\" from the json-schema-tracking-generator:run task.
@Generated
object TrackingSchemasVersion {
    const val VERSION = \"$VERSION\"
}" >"$VERSION_OBJECT"
